$ErrorActionPreference = "Stop"

Write-Host "=== SaborFlow - Etapa 13.3 Recuperacao segura do 2FA ===" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "package.json")) {
    throw "Execute este script na pasta principal do projeto SaborFlow."
}

if (-not (Test-Path "database\migrations\028_admin_totp_2fa.sql")) {
    throw "A Etapa 13.2 nao foi encontrada. A migration 028 precisa existir antes da 13.3."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Etapa13-3-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "lib\security\two-factor.ts",
    "components\admin\security-panel.tsx",
    "database\migrations\029_admin_2fa_recovery_management.sql",
    "app\api\admin\2fa\security\route.ts",
    "app\api\admin\2fa\recovery-codes\route.ts",
    "app\api\admin\2fa\reconfigure\route.ts",
    "app\api\admin\2fa\reconfigure\qr\route.ts"
)

foreach ($file in $targets) {
    if (Test-Path $file) {
        $backupPath = Join-Path $backupRoot $file
        $backupDir = Split-Path $backupPath -Parent
        New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
        Copy-Item $file $backupPath -Force
    }
}

Write-Host "Backup criado em:" -ForegroundColor Green
Write-Host $backupRoot
Write-Host ""

function Write-Base64File {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $directory = Split-Path $Path -Parent
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), $bytes)
}

Write-Host "Gravando lib\security\two-factor.ts..."
Write-Base64File -Path "lib\security\two-factor.ts" -Base64 ""

Write-Host "Gravando components\admin\security-panel.tsx..."
Write-Base64File -Path "components\admin\security-panel.tsx" -Base64 ""

Write-Host "Gravando database\migrations\029_admin_2fa_recovery_management.sql..."
Write-Base64File -Path "database\migrations\029_admin_2fa_recovery_management.sql" -Base64 ""

Write-Host "Gravando app\api\admin\2fa\security\route.ts..."
Write-Base64File -Path "app\api\admin\2fa\security\route.ts" -Base64 ""

Write-Host "Gravando app\api\admin\2fa\recovery-codes\route.ts..."
Write-Base64File -Path "app\api\admin\2fa\recovery-codes\route.ts" -Base64 ""

Write-Host "Gravando app\api\admin\2fa\reconfigure\route.ts..."
Write-Base64File -Path "app\api\admin\2fa\reconfigure\route.ts" -Base64 ""

Write-Host "Gravando app\api\admin\2fa\reconfigure\qr\route.ts..."
Write-Base64File -Path "app\api\admin\2fa\reconfigure\qr\route.ts" -Base64 ""

Write-Host ""
Write-Host "Etapa 13.3 aplicada localmente." -ForegroundColor Green
Write-Host "Incluido:" -ForegroundColor Green
Write-Host " - status do 2FA e quantidade de codigos restantes"
Write-Host " - regeneracao protegida dos codigos de recuperacao"
Write-Host " - troca controlada do Authenticator"
Write-Host " - QR temporario para o novo Authenticator"
Write-Host " - autenticador antigo permanece valido ate confirmar o novo"
Write-Host " - sem botao simples para desativar 2FA"
Write-Host ""
Write-Host "IMPORTANTE: a migration 029 foi apenas criada. Ela NAO foi executada no banco." -ForegroundColor Yellow
Write-Host ""
git status --short
